/// The root `AGENTS.md` / `CLAUDE.md` pointer to `.agents/`;
/// [agentsMdPointerLine] is what gets appended to an existing file.
String agentsMdTemplate() =>
    '''
# AI agents

$agentsMdPointerLine
''';

/// The one line added to an existing `AGENTS.md` / `CLAUDE.md`.
const agentsMdPointerLine =
    'Read every file in the `.agents/` folder for rules and context before '
    'changing code (generated by `clean-helper add-agent-context`).';
